(()=>{const svg=p=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+p+'</svg>',icons={calendar:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M4 10h16"/>',list:'<path d="M9 6h12M9 12h12M9 18h12M3 6h.1M3 12h.1M3 18h.1"/>',check:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',gear:'<path d="M3 5h3m4 0h11M3 12h11m4 0h3M3 19h3m4 0h11"/><circle cx="8" cy="5" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="8" cy="19" r="2"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0v5l-2 4h16l-2-4zM10 21h4"/>',refresh:'<path d="M20 4v6h-6M20 10a8 8 0 1 0 .1 5"/>',file:'<path d="M14 3H5v18h14V8zM14 3v5h5M8 12h8M8 16h8"/>',sheet:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 9v12M3 15h18"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>'};document.querySelectorAll('#stats .label').forEach((el,i)=>el.textContent=['Missions du jour','À réaliser','Clôturées ce mois','Heures déclarées'][i]);const stat=document.querySelectorAll('#stats .ama-stat-head svg');['calendar','list','check','clock'].forEach((key,i)=>{stat[i].innerHTML=icons[key]});document.querySelector('#adminTab .ama-nav-ico').innerHTML=svg(icons.gear);document.querySelector('#amaBell>svg').innerHTML=icons.bell;document.getElementById('refreshBtn').innerHTML=svg(icons.refresh)+'<span>Actualiser</span>';document.getElementById('refreshBtn').setAttribute('aria-label','Actualiser les données');[['downloadHoursPdf','file'],['downloadHoursExcel','sheet'],['emailHoursReport','mail']].forEach(([id,key])=>{const el=document.getElementById(id);el.insertAdjacentHTML('afterbegin',svg(icons[key]))});})();